  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Places the current front pipe from the queue onto the specified board position.
   * Algorithm:
   * 1. Convert the player-facing row directly to the internal row index.
   * 2. Convert the column letter to an internal column index by mapping 'A' to 1, 'B' to 2, and so on.
   * 3. Read the pipe at the front of the pipe queue.
   * 4. Ask the map to place that pipe at the target coordinate.
   * 5. If placement succeeds:
   *    a. Remove the pipe from the queue.
   *    b. Record the placed cell in the cell stack/history.
   *    c. Increment the step counter.
   *    d. Return true.
   * 6. If placement fails, do not modify the queue or history and return false.
   * Related Features:
   * - numOfSteps
   * - cellStack
   * - pipeQueue
   * - map
   * Related Classes: Map, PipeQueue, CellStack, Pipe
   * Input:
   * - row: player-facing row number, using the same value as the playable internal row index.
   * - col: player-facing column letter, where 'A' maps to 1.
   * Output:
   * - boolean: true if the pipe was placed successfully; otherwise false.
   * Pre-condition:
   * - The Game object has been initialized.
   * - The pipe queue is not empty.
   * - The target coordinate is intended to be within the playable area.
   * Post-condition:
   * - On success, the target fillable cell contains the current pipe.
   * - The consumed pipe is removed from the queue and the queue may be refilled to its maximum length.
   * - The placed cell is stored in placement history.
   * - numOfSteps increases by one.
   * - On failure, game state is unchanged except for any non-observable checks.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean placePipe(final int row, final char col)
  {
    PipeQueue queue = getPipeQueue();
    Map gameMap = getMap();
    CellStack stack = getCellStack();
    if (queue == null || gameMap == null || stack == null)
    {
      return false;
    }

    int colIndex = Character.toUpperCase(col) - 'A' + 1;
    Pipe currentPipe = queue.getPipes().isEmpty() ? null : queue.getPipes().get(0);
    if (currentPipe == null)
    {
      return false;
    }

    if (gameMap.getFillableCell(row, colIndex) != null && gameMap.getFillableCell(row, colIndex).setPipe(currentPipe))
    {
      queue.getPipes().remove(0);
      stack.push(gameMap.getFillableCell(row, colIndex));
      setNumOfSteps(getNumOfSteps() + 1);
      return true;
    }

    return false;
  }

